<template><div><el-form inline @submit.prevent="search"><el-form-item><el-checkbox v-model="unread">只看未读</el-checkbox></el-form-item><el-form-item><el-button type="primary" @click="search">刷新消息</el-button></el-form-item></el-form><el-alert title="消息仅是提醒，已读不代表业务已处理；打开时会重新检查权限。消息保留30天。" :closable="false"/><el-table :data="rows" v-loading="loading"><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.readAt?'info':'warning'">{{s.row.readAt?'已读':'未读'}}</el-tag></template></el-table-column><el-table-column prop="subject" label="消息" min-width="200"/><el-table-column prop="resourceId" label="对象编号" width="100"/><el-table-column prop="createTime" label="时间" width="170"/><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="open(s.row)">打开任务</el-button><el-button v-if="!s.row.readAt" link @click="read(s.row)">已读</el-button></template></el-table-column></el-table><pagination v-if="total" :total="total" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="load"/></div></template>
<script setup>
import{ref,reactive,onMounted,onBeforeUnmount,onDeactivated}from'vue';import{useRouter}from'vue-router';import{workflow,notificationTarget}from'@/api/cms/workflow';const emit=defineEmits(['changed','open']),router=useRouter(),rows=ref([]),total=ref(0),loading=ref(false),unread=ref(false),pg=reactive({pageNum:1,pageSize:10});let epoch=0
async function load(){const n=++epoch;loading.value=true;try{const r=await workflow('notifications/list','get',undefined,{unread:unread.value,...pg});if(n===epoch){rows.value=r.rows;total.value=r.total;emit('changed')}}finally{if(n===epoch)loading.value=false}}function search(){pg.pageNum=1;load()}
async function read(row){await workflow(`notifications/${row.notificationId}/read`,'post',{version:row.version});await load()}
async function open(row){const n=epoch;const r=await workflow(`notifications/${row.notificationId}/read`,'post',{version:row.version});if(n!==epoch)return;emit('open');router.push(notificationTarget(r.data));await load()}
function close(){++epoch;rows.value=[];total.value=0}onMounted(load);onBeforeUnmount(close);onDeactivated(close);defineExpose({load,close})
</script>
